<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';import{Refresh,Setting}from'@element-plus/icons-vue';
import { apiRequest } from '../../lib/api.js';
const props=defineProps({accounts:{type:Array,default:()=>[]}});const conversationLimit=ref(''),notice=ref(''),open=ref(false),selected=ref(null),loading=ref(false),saving=ref(false);const limits=reactive({daily:'',total:''});const stats=ref({});
const rows=computed(()=>props.accounts.map(account=>{const s=stats.value[account.id]||{};const reached=(s.dailyLimit!=null&&s.today>=s.dailyLimit)||(s.totalLimit!=null&&s.total>=s.totalLimit);return{...account,today:s.today||0,totalCount:s.total||0,conversations:s.conversations||0,dailyLimit:s.dailyLimit??'不限',totalLimit:s.totalLimit??'不限',reached}}));
const summary=computed(()=>({conversations:rows.value.reduce((sum,row)=>sum+row.conversations,0),today:rows.value.reduce((sum,row)=>sum+row.today,0)}));
function valid(value){return !value||(/^\d+$/.test(value)&&Number(value)>0)}
const toNumber=value=>String(value).trim()===''?null:Number(value);
async function load(){loading.value=true;try{const data=await apiRequest('automation-limits');conversationLimit.value=data.conversationLimit==null?'':String(data.conversationLimit);stats.value=Object.fromEntries(data.accounts.map(item=>[item.account,item]))}catch(cause){notice.value=cause.message}finally{loading.value=false}}
async function saveConversation(){if(!valid(conversationLimit.value)){notice.value='会话发送上限格式错误，必须是正整数。';return}saving.value=true;try{await apiRequest('automation-limits',{method:'PUT',body:{conversationLimit:toNumber(conversationLimit.value)}});notice.value='统一会话上限已保存。';await load()}catch(cause){notice.value=cause.message}finally{saving.value=false}}
function edit(row){selected.value=row;const s=stats.value[row.id]||{};limits.daily=s.dailyLimit==null?'':String(s.dailyLimit);limits.total=s.totalLimit==null?'':String(s.totalLimit);open.value=true}
async function saveAccount(){if(!valid(limits.daily)||!valid(limits.total)){notice.value='触发上限格式错误，必须是正整数。';return}saving.value=true;try{await apiRequest('automation-limits',{method:'PUT',body:{account:selected.value.id,dailyLimit:toNumber(limits.daily),totalLimit:toNumber(limits.total)}});open.value=false;notice.value='账号触发上限已保存。';await load()}catch(cause){notice.value=cause.message}finally{saving.value=false}}
onMounted(load);watch(()=>props.accounts.length,load);
</script>
<template><section class="automation-settings" aria-label="自动化设置"><header><div><h1>自动化设置</h1><p>当前为整用户统一配置，作用于该用户下全部账号和全部聊天会话。</p></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></header><el-alert v-if="notice" :title="notice" type="info" show-icon @close="notice=''"/><section class="conversation-limit"><div class="limit-icon"><el-icon><Setting/></el-icon></div><div><h2>统一会话上限</h2><p>按用户统一配置单会话每日自动化发送上限，命中上限后该会话会被直接拦截。</p><small>按用户时区统计自然日；留空表示不限。</small></div><div class="limit-editor"><el-input v-model="conversationLimit" aria-label="单会话每日发送上限" placeholder="不限" inputmode="numeric"><template #prepend>单会话每日发送上限</template></el-input><el-button type="primary" :loading="saving" @click="saveConversation">保存</el-button></div></section><section class="account-limits"><div class="section-heading"><div><h2>设置账号触发上限</h2><small>账号数 {{rows.length}} · 会话总数 {{summary.conversations}} · 今日自动化发送 {{summary.today}}</small></div></div><el-table :data="rows" empty-text="暂无账号自动化数据"><el-table-column prop="name" label="账号" min-width="150"/><el-table-column prop="today" label="今日触发次数" width="120"/><el-table-column prop="dailyLimit" label="每日触发上限" width="120"/><el-table-column prop="totalCount" label="总触发次数" width="110"/><el-table-column prop="totalLimit" label="累计总上限" width="110"/><el-table-column prop="conversations" label="会话数" width="90"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag size="small" :type="row.reached?'danger':'success'">{{row.reached?'已达上限':'可触发'}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="edit(row)">设置上限</el-button></template></el-table-column></el-table></section><el-dialog v-model="open" title="设置账号触发上限" width="min(520px,94vw)"><p>{{selected?.nickname||selected?.name||'未命名账号'}}</p><el-form label-position="top"><el-form-item label="每日触发上限"><el-input v-model="limits.daily" placeholder="留空表示不限" inputmode="numeric"/></el-form-item><el-form-item label="累计总上限"><el-input v-model="limits.total" placeholder="留空表示不限" inputmode="numeric"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAccount">保存</el-button></template></el-dialog></section></template>
<style scoped>.automation-settings{display:grid;gap:14px;min-width:0}.automation-settings>header{display:flex;align-items:center;justify-content:space-between}.automation-settings h1{font-size:20px;margin:0}.automation-settings header p,.conversation-limit p,.conversation-limit small,.section-heading small{color:#7f8da1;font-size:12px;margin:5px 0}.conversation-limit,.account-limits{background:#fff;border-radius:17px;box-shadow:0 4px 12px #35497905}.conversation-limit{padding:22px;display:grid;grid-template-columns:auto minmax(220px,1fr) minmax(300px,560px);gap:16px;align-items:center}.limit-icon{width:44px;height:44px;border-radius:12px;background:#eaf2ff;color:#3474df;display:grid;place-items:center}.conversation-limit h2,.section-heading h2{font-size:17px;margin:0}.limit-editor{display:flex;gap:10px}.account-limits{padding:20px;min-height:520px;overflow:hidden}.section-heading{margin-bottom:16px}.account-limits :deep(.el-table__empty-block){min-height:390px}@media(max-width:850px){.conversation-limit{grid-template-columns:auto 1fr}.limit-editor{grid-column:1/-1}}@media(max-width:650px){.automation-settings>header{align-items:start;gap:10px}.conversation-limit{padding:15px}.limit-editor{flex-direction:column}.account-limits{padding:12px}}</style>
